package com.lostpropertydiary;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LostPropertyDiaryPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LostPropertyDiaryPlugin.class);
		RuneLite.main(args);
	}
}

package com.lostpropertydiary;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class DiaryRewardTest
{
	@Test
	public void everyRewardHasFourTiersAndFourVarbits()
	{
		for (DiaryReward reward : DiaryReward.values())
		{
			assertEquals(reward + " should have 4 tier item ids", 4, reward.getTierItemIds().length);
			assertEquals(reward + " should have 4 tier varbits", 4, reward.getTierVarbits().length);
			assertTrue(reward + " should have a base item id", reward.getBaseItemId() > 0);
		}
	}

	@Test
	public void allItemIdsAreUniqueAndMapBackToTheirReward()
	{
		// Every base id and tier id must be distinct across all families, otherwise byItemId would
		// return the wrong reward for a shop slot.
		Map<Integer, DiaryReward> owner = new HashMap<>();
		for (DiaryReward reward : DiaryReward.values())
		{
			recordUnique(owner, reward.getBaseItemId(), reward);
			for (int tierId : reward.getTierItemIds())
			{
				recordUnique(owner, tierId, reward);
			}
		}

		// And the lookup the plugin actually uses must agree.
		for (Map.Entry<Integer, DiaryReward> e : owner.entrySet())
		{
			assertSame("byItemId mismatch for " + e.getKey(), e.getValue(), DiaryReward.byItemId(e.getKey()));
		}
	}

	private static void recordUnique(Map<Integer, DiaryReward> owner, int id, DiaryReward reward)
	{
		DiaryReward prev = owner.put(id, reward);
		assertNull("item id " + id + " is shared by " + prev + " and " + reward, prev);
	}

	@Test
	public void unknownItemIdReturnsNull()
	{
		assertNull(DiaryReward.byItemId(-1));
		assertNull(DiaryReward.byItemId(0));
		assertNull(DiaryReward.byItemId(Integer.MAX_VALUE));
	}

	@Test
	public void highestCompletedTierPicksTheTopCompletedTier()
	{
		DiaryReward karamja = DiaryReward.KARAMJA_GLOVES;
		int[] varbits = karamja.getTierVarbits();

		// nothing complete
		assertEquals(-1, karamja.highestCompletedTier(completed()));
		assertEquals(-1, karamja.highestCompletedItemId(completed()));

		// only easy
		assertEquals(0, karamja.highestCompletedTier(completed(varbits[0])));
		assertEquals(karamja.getTierItemIds()[0], karamja.highestCompletedItemId(completed(varbits[0])));

		// up to hard (easy+medium+hard set) -> tier 2
		assertEquals(2, karamja.highestCompletedTier(completed(varbits[0], varbits[1], varbits[2])));

		// elite -> tier 3
		assertEquals(3, karamja.highestCompletedTier(completed(varbits[0], varbits[1], varbits[2], varbits[3])));
		assertEquals(karamja.getTierItemIds()[3], karamja.highestCompletedItemId(completed(varbits[0], varbits[1], varbits[2], varbits[3])));
	}

	@Test
	public void onlyTheConfiguredVarbitsAreConsulted()
	{
		// A reward must not be influenced by another family's varbit being set.
		DiaryReward falador = DiaryReward.FALADOR_SHIELD;
		int someoneElsesVarbit = DiaryReward.ARDOUGNE_CLOAK.getTierVarbits()[3];
		assertEquals(-1, falador.highestCompletedTier(completed(someoneElsesVarbit)));
	}

	/** Returns a varbit resolver where the given varbit ids report value 1 and all others 0. */
	private static IntUnaryOperator completed(int... setVarbits)
	{
		Set<Integer> set = new HashSet<>();
		for (int v : setVarbits)
		{
			set.add(v);
		}
		return id -> set.contains(id) ? 1 : 0;
	}
}

package com.lostpropertydiary;

import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Lost Property Diary Tiers",
	description = "Shows the correct achievement diary reward tier in the Lost Property shop instead of always the easy tier",
	tags = {"perdu", "diary", "achievement", "shop", "reclaim", "lost", "property"}
)
public class LostPropertyDiaryPlugin extends Plugin
{
	@Inject
	private Client client;

	private boolean shopOpen;

	@Override
	protected void shutDown()
	{
		shopOpen = false;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.LOST_PROPERTY)
		{
			shopOpen = true;
			applyDiaryTiers();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.LOST_PROPERTY)
		{
			shopOpen = false;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// While the shop is open, re-apply after every script. The interface fills its slots
		// incrementally over several scripts and re-writes them with the base icons, so a one-shot
		// apply would either run too early (before the items exist) or get overwritten. Re-applying
		// on each script's completion corrects the slots within the same cycle the populate runs,
		// before that frame renders, so there's no flash and it copes with the incremental fill.
		// It's a no-op (a cheap boolean check) whenever the shop isn't open.
		if (shopOpen)
		{
			applyDiaryTiers();
		}
	}

	private void applyDiaryTiers()
	{
		Widget list = client.getWidget(InterfaceID.LostProperty.LIST);
		if (list == null)
		{
			return;
		}

		Widget[] slots = list.getDynamicChildren();
		if (slots == null)
		{
			return;
		}

		for (Widget slot : slots)
		{
			int displayedId = slot.getItemId();
			DiaryReward reward = DiaryReward.byItemId(displayedId);
			if (reward == null)
			{
				continue;
			}

			int correctId = reward.highestCompletedItemId(client);
			if (correctId != -1 && correctId != displayedId)
			{
				slot.setItemId(correctId);
				// The shop labels the slot with the generic base name (e.g. "Karamja gloves"),
				// which doesn't update with the icon, so set it to match the tier we're showing,
				// using the same "<col=ff9040>" formatting the shop uses for its slot names.
				slot.setName("<col=ff9040>" + client.getItemDefinition(correctId).getName());

				// Captured only when RuneLite is run with debug logging; useful if a future game
				// update changes an item id and a reward stops updating.
				log.debug("Swapped {} from id {} to tier id {}", reward, displayedId, correctId);
			}
		}
	}
}

package com.lostpropertydiary;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Varbits;

/**
 * One achievement-diary reward family (e.g. Karamja gloves), holding the completion varbit and the
 * item id for each of its four tiers. Tiers are 0-indexed internally: 0 = easy/1, 3 = elite/4.
 *
 * <p>{@code baseItemId} is the generic, pre-tier item id that the Lost Property shop displays
 * for this reward. It always shows that base icon regardless of which tier you've completed, which
 * is what this plugin corrects.
 *
 * <p>The completion varbits come from {@link net.runelite.api.Varbits}; the item ids were pulled
 * from the OSRS Wiki and confirmed in-game. If any reward shows the wrong tier, enable debug
 * logging in the config to print the shop slots and verify these.
 */
@Getter
enum DiaryReward
{
	KARAMJA_GLOVES(1686,
		new int[]{Varbits.DIARY_KARAMJA_EASY, Varbits.DIARY_KARAMJA_MEDIUM, Varbits.DIARY_KARAMJA_HARD, Varbits.DIARY_KARAMJA_ELITE},
		new int[]{11136, 11138, 11140, 13103}),
	ARDOUGNE_CLOAK(770,
		new int[]{Varbits.DIARY_ARDOUGNE_EASY, Varbits.DIARY_ARDOUGNE_MEDIUM, Varbits.DIARY_ARDOUGNE_HARD, Varbits.DIARY_ARDOUGNE_ELITE},
		new int[]{13121, 13122, 13123, 13124}),
	FALADOR_SHIELD(762,
		new int[]{Varbits.DIARY_FALADOR_EASY, Varbits.DIARY_FALADOR_MEDIUM, Varbits.DIARY_FALADOR_HARD, Varbits.DIARY_FALADOR_ELITE},
		new int[]{13117, 13118, 13119, 13120}),
	FREMENNIK_SEA_BOOTS(10510,
		new int[]{Varbits.DIARY_FREMENNIK_EASY, Varbits.DIARY_FREMENNIK_MEDIUM, Varbits.DIARY_FREMENNIK_HARD, Varbits.DIARY_FREMENNIK_ELITE},
		new int[]{13129, 13130, 13131, 13132}),
	KANDARIN_HEADGEAR(6450,
		new int[]{Varbits.DIARY_KANDARIN_EASY, Varbits.DIARY_KANDARIN_MEDIUM, Varbits.DIARY_KANDARIN_HARD, Varbits.DIARY_KANDARIN_ELITE},
		new int[]{13137, 13138, 13139, 13140}),
	DESERT_AMULET(5573,
		new int[]{Varbits.DIARY_DESERT_EASY, Varbits.DIARY_DESERT_MEDIUM, Varbits.DIARY_DESERT_HARD, Varbits.DIARY_DESERT_ELITE},
		new int[]{13133, 13134, 13135, 13136}),
	EXPLORERS_RING(5095,
		new int[]{Varbits.DIARY_LUMBRIDGE_EASY, Varbits.DIARY_LUMBRIDGE_MEDIUM, Varbits.DIARY_LUMBRIDGE_HARD, Varbits.DIARY_LUMBRIDGE_ELITE},
		new int[]{13125, 13126, 13127, 13128}),
	MORYTANIA_LEGS(5093,
		new int[]{Varbits.DIARY_MORYTANIA_EASY, Varbits.DIARY_MORYTANIA_MEDIUM, Varbits.DIARY_MORYTANIA_HARD, Varbits.DIARY_MORYTANIA_ELITE},
		new int[]{13112, 13113, 13114, 13115}),
	VARROCK_ARMOUR(5087,
		new int[]{Varbits.DIARY_VARROCK_EASY, Varbits.DIARY_VARROCK_MEDIUM, Varbits.DIARY_VARROCK_HARD, Varbits.DIARY_VARROCK_ELITE},
		new int[]{13104, 13105, 13106, 13107}),
	WILDERNESS_SWORD(3981,
		new int[]{Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM, Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE},
		new int[]{13108, 13109, 13110, 13111}),
	WESTERN_BANNER(3983,
		new int[]{Varbits.DIARY_WESTERN_EASY, Varbits.DIARY_WESTERN_MEDIUM, Varbits.DIARY_WESTERN_HARD, Varbits.DIARY_WESTERN_ELITE},
		new int[]{13141, 13142, 13143, 13144}),
	RADAS_BLESSING(22803,
		new int[]{Varbits.DIARY_KOUREND_EASY, Varbits.DIARY_KOUREND_MEDIUM, Varbits.DIARY_KOUREND_HARD, Varbits.DIARY_KOUREND_ELITE},
		new int[]{22941, 22943, 22945, 22947});

	private final int baseItemId;
	private final int[] tierVarbits;
	private final int[] tierItemIds;

	DiaryReward(int baseItemId, int[] tierVarbits, int[] tierItemIds)
	{
		this.baseItemId = baseItemId;
		this.tierVarbits = tierVarbits;
		this.tierItemIds = tierItemIds;
	}

	private static final Map<Integer, DiaryReward> BY_ITEM_ID = new HashMap<>();

	static
	{
		for (DiaryReward reward : values())
		{
			// Map the shop's base id and every tier id back to this family, so a slot is matched
			// whether it shows the base icon (the usual case) or an already-tiered icon.
			BY_ITEM_ID.put(reward.baseItemId, reward);
			for (int itemId : reward.tierItemIds)
			{
				BY_ITEM_ID.put(itemId, reward);
			}
		}
	}

	/**
	 * @return the reward family that {@code itemId} belongs to (its base id or any tier id), or
	 * {@code null} if the id is not a tracked diary reward.
	 */
	static DiaryReward byItemId(int itemId)
	{
		return BY_ITEM_ID.get(itemId);
	}

	int highestCompletedTier(Client client)
	{
		return highestCompletedTier(client::getVarbitValue);
	}

	/**
	 * @param varbitValue resolves a varbit id to its current value (a tier is complete when &gt; 0)
	 * @return the 0-indexed highest tier the player has completed (0 = easy .. 3 = elite), or -1 if
	 * no tier of this diary is complete.
	 */
	int highestCompletedTier(IntUnaryOperator varbitValue)
	{
		int highest = -1;
		for (int i = 0; i < tierVarbits.length; i++)
		{
			if (varbitValue.applyAsInt(tierVarbits[i]) > 0)
			{
				highest = i;
			}
		}
		return highest;
	}

	int highestCompletedItemId(Client client)
	{
		return highestCompletedItemId(client::getVarbitValue);
	}

	/**
	 * @return the item id of the highest completed tier, or -1 if no tier is complete.
	 */
	int highestCompletedItemId(IntUnaryOperator varbitValue)
	{
		int tier = highestCompletedTier(varbitValue);
		return tier < 0 ? -1 : tierItemIds[tier];
	}
}
